#include "model.hpp"
#include <iostream>
int main(int argc,char**argv){Model m(read(argv[1]));double mismatch=0,normerror=0;for(int i=0;i<20;++i){Eigen::Matrix<double,13,1>x=Eigen::Matrix<double,13,1>::Zero();x[2]=2;x[6]=1.;x[7]=.1*i;x.segment<4>(6).normalize();x.tail<3>()=Eigen::Vector3d(.3*i,-.1*i,.2*i);Eigen::Vector4d u;u<<2+.03*i,2.2,2.1,2.3;double h=.01+.004*i;auto exact=m.step(std::vector<DM>{dm(x),dm(u),DM(h)})[0].get_elements();auto numeric=x;for(int k=0;k<Model::integration_substeps;++k)numeric=m.rk4(numeric,u,h/Model::integration_substeps);for(int k=0;k<13;++k)mismatch=std::max(mismatch,std::abs(numeric[k]-exact[k]));normerror=std::max(normerror,std::abs(numeric.segment<4>(6).norm()-1.));}Json result={{"casadi_numeric_max_error",mismatch},{"unit_quaternion_max_error",normerror},{"passed",mismatch<1e-10&&normerror<1e-4}};std::cout<<result.dump(2)<<'\n';return result["passed"].get<bool>()?0:1;}
